from urllib.parse import urlparse
ALLOWED_SCHEMES = ("http", "https")
def is_valid_url(url):
    if not isinstance(url, str):
        return False
    p = urlparse(url.strip())
    return p.scheme in ALLOWED_SCHEMES and bool(p.netloc)

